import sanitizeHtml from "sanitize-html";

import { LOGO_TOKEN_PATTERN, escapeHtml, renderTokens, type TokenValues } from "@/lib/mailer/tokens";

/**
 * Full-HTML emails: written in the CKEditor (features/mailer/components/
 * html-email-editor.tsx) or generated by AI (lib/mailer/ai-email.ts), and
 * stored on a template/campaign as `html`. An email with `html` is sent as
 * that document; the plain-text `body` is only its text alternative.
 *
 * Every save and every render runs the HTML through sanitizeEmailHtml —
 * an allowlist of email-safe tags and attributes, no scripts, forms,
 * iframes or event handlers, and links/images only over http(s)/mailto/tel
 * (images may also be inline data: URLs, like the Brand Settings logo).
 * The rendered email always gets our own footer with the unsubscribe link,
 * whatever the HTML contains.
 */

/** Kept small on purpose: live Mailer data is one Firestore document (1 MiB for everything). */
export const EMAIL_HTML_MAX = 50_000;

const TAGS = [
  "html", "head", "body", "title", "meta", "style",
  "table", "thead", "tbody", "tfoot", "tr", "td", "th", "caption", "colgroup", "col",
  "div", "span", "p", "br", "hr", "center", "font",
  "h1", "h2", "h3", "h4", "h5", "h6",
  "a", "img", "figure", "figcaption",
  "strong", "b", "em", "i", "u", "s", "strike", "del", "ins", "sup", "sub", "small", "mark", "code", "pre", "blockquote",
  "ul", "ol", "li",
];

const COMMON_ATTRS = [
  "style", "class", "id", "align", "valign", "width", "height", "bgcolor", "background", "border",
  "cellpadding", "cellspacing", "role", "dir", "lang", "title", "color", "face", "size",
  "colspan", "rowspan", "span", "nowrap",
];

const OPTIONS: sanitizeHtml.IOptions = {
  allowedTags: TAGS,
  allowedAttributes: {
    "*": COMMON_ATTRS,
    a: [...COMMON_ATTRS, "href", "target", "name", "rel"],
    img: [...COMMON_ATTRS, "src", "alt"],
    meta: ["name", "content", "charset"],
    html: ["lang", "dir", "xmlns"],
    ol: [...COMMON_ATTRS, "start", "type"],
  },
  allowedSchemes: ["http", "https", "mailto", "tel"],
  allowedSchemesByTag: { img: ["http", "https", "data"] },
  allowedSchemesAppliedToAttributes: ["href", "src", "background"],
  allowProtocolRelative: false,
  // <style> in <head> is normal for email; its contents are cleaned below.
  allowVulnerableTags: true,
  nonTextTags: ["script", "textarea", "option", "noscript", "iframe", "object", "embed", "svg", "math", "template"],
  // Keep the HTML as written (entities, attribute order) where it's allowed.
  parser: { lowerCaseTags: true, lowerCaseAttributeNames: true },
};

/** Things CSS must never do here: load other stylesheets, run script, use old IE behaviours. */
function cleanCss(css: string): string {
  return css
    .replace(/@import[^;]*;?/gi, "")
    .replace(/expression\s*\(/gi, "")
    .replace(/(?:java|vb)script\s*:/gi, "")
    .replace(/-moz-binding|behavior\s*:/gi, "")
    .replace(/<\/?\s*style/gi, "");
}

export function sanitizeEmailHtml(html: string): string {
  const clean = sanitizeHtml(html, {
    ...OPTIONS,
    // An image whose src was unsafe and removed is just dropped.
    exclusiveFilter: (frame) => frame.tag === "img" && !frame.attribs.src,
    transformTags: {
      "*": (tagName, attribs) => {
        if (attribs.style) attribs.style = cleanCss(attribs.style);
        if (tagName === "a" && attribs.target === "_blank") attribs.rel = "noopener noreferrer";
        return { tagName, attribs };
      },
    },

  });
  return clean.replace(/(<style[^>]*>)([\s\S]*?)(<\/style>)/gi, (_m, open: string, css: string, close: string) => open + cleanCss(css) + close);
}

/** Splits a document into what CKEditor edits (the <body> content) and the shell around it. */
export function splitEmailDocument(html: string): { before: string; inner: string; after: string } {
  const open = /<body\b[^>]*>/i.exec(html);
  const closeAt = html.search(/<\/body\s*>/i);
  if (!open || closeAt < open.index + open[0].length) {
    return { before: "", inner: html, after: "" };
  }
  const start = open.index + open[0].length;
  return { before: html.slice(0, start), inner: html.slice(start, closeAt), after: html.slice(closeAt) };
}

/** Puts edited body content back into its document shell (or a plain one for a bare fragment). */
export function joinEmailDocument(before: string, inner: string, after: string): string {
  if (before && after) return before + inner + after;
  return wrapEmailDocument(inner);
}

export function wrapEmailDocument(inner: string): string {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
</head>
<body style="margin:0;padding:0;background:#f4f4f7;">
${inner}
</body>
</html>`;
}

/** The email's readable text — for the plain-text part, template cards and AI context. */
export function htmlToText(html: string): string {
  const withBreaks = html
    .replace(/<\s*br\s*\/?>/gi, "\n")
    .replace(/<\/(p|div|h[1-6]|li|tr|table|blockquote)\s*>/gi, "\n")
    .replace(/<\s*li\b[^>]*>/gi, "• ");
  const text = sanitizeHtml(withBreaks, { allowedTags: [], allowedAttributes: {}, nonTextTags: ["script", "style", "title", "head", "textarea", "option", "noscript"] });
  return text
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/[ \t ]+/g, " ")
    .replace(/ *\n */g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

/**
 * Personalises a stored HTML email for one recipient: {{tokens}} become
 * escaped values, {{logo}} becomes the Brand Settings logo (or nothing),
 * then the whole document is sanitized again and gets the preheader and our
 * footer (sender + unsubscribe link).
 */
export function renderHtmlEmail(
  html: string,
  values: TokenValues,
  options: { logoSrc: string | null; logoAlt: string; preheader: string; footerHtml: string },
): { html: string; text: string } {
  const logo = options.logoSrc
    ? `<img src="${escapeHtml(options.logoSrc)}" alt="${escapeHtml(options.logoAlt)}" height="56" style="display:inline-block;height:56px;width:auto;max-width:240px;border:0;outline:none;text-decoration:none;">`
    : "";
  const escapedValues = Object.fromEntries(Object.entries(values).map(([k, v]) => [k, escapeHtml(v)])) as TokenValues;
  const personal = html
    .split(LOGO_TOKEN_PATTERN)
    .map((part) => renderTokens(part, escapedValues))
    .join(logo);
  const clean = sanitizeEmailHtml(personal);
  const { before, inner, after } = splitEmailDocument(clean);
  const preheader = options.preheader
    ? `<div style="display:none;max-height:0;overflow:hidden;opacity:0;">${escapeHtml(options.preheader)}</div>`
    : "";
  const body = `${preheader}\n${inner}\n${options.footerHtml}`;
  const doc = before && after ? `<!doctype html>\n${before}${body}${after}` : wrapEmailDocument(body);
  return { html: doc, text: htmlToText(inner) };
}
